from h import *
R(9517824,"ذرة على الكوز بقلاية الهواء",
"الذرة على الكوز بقلاية الهواء لذيذة وسهلة التحضير وطعمها كأنها مشوية على الفحم، ولكن دون الحاجة إلى إشعال الشواية! سهلة جدًا وتجهز في وقت قصير للغاية.",
"3 حصص","حصة واحدة",
["3 كيزان ذرة مقشّرة","1-2 ملعقة صغيرة سمن نباتي (مارجرين) أو زيت من اختيارك، اختياري"],
["قشّر الذرة وقطّعها إلى نصفين إذا لزم الأمر لتناسب سلة القلاية. وإذا كانت تناسب كاملة، فلا حاجة إلى تقطيعها. وإذا كنت ستستخدم السمن النباتي (المارجرين) أو الزيت، فادهن الذرة به باستخدام فرشاة سيليكون. أو رشّها برذاذ زيت الطهي. (اختياري)","ضع الذرة في السلة واقلِها بالهواء الساخن على 380 درجة فهرنهايت (195 درجة مئوية) لمدة 12-15 دقيقة. قلّب الذرة عند الدقيقة 8-10 تقريبًا وواصل تقليبها كل دقيقتين تقريبًا قرب نهاية الطهي، لتتأكد من عدم احتراقها.","قدّمها دافئة كما هي، أو مع الزبدة أو الكريما فريسكا أو الكزبرة الخضراء أو القرفة أو أي إضافات تفضلها."],
["اختر ذرة طازجة بحبوب أسمك. يجب أن تكون القشور ملفوفة بإحكام وخضراء زاهية وليست مائلة إلى الأصفر أو جافة. بحسب طراز قلاية الهواء لديك، يمكنك تقطيع الذرة إلى نصفين لتناسب المساحة عند الحاجة. سيؤثر عدد الكيزان وطراز القلاية على وقت الطهي، لذا ابدأ بتفقد الذرة عند الدقيقة العاشرة تقريبًا. لوصفة خالية من الزيت، احذف السمن النباتي أو الزيت وادهن الذرة بقليل من مرق الخضار بدلًا منه، للحفاظ على رطوبتها أثناء الطهي."])
R(9517941,"برجر السيتان القابل للشواء",
"برجر سيتان طري ومشبع ولذيذ بشكل لا يصدق ويتحمل الشواء على الشواية!",
"8 برجر سيتان","حصة واحدة",
["¾ كوب فاصولياء سوداء مطبوخة أو معلبة","4 أونصات فطر أبيض","2 ملعقة كبيرة معجون الميسو الأبيض","1 ملعقة كبيرة طحينة","2 ملعقة صغيرة مسحوق البصل","2 ملعقة صغيرة مسحوق الثوم","2 ملعقة صغيرة بابريكا مدخنة","½ كوب مرق خضار","280 جرامًا من غلوتين القمح الحيوي، أي حوالي 2¼ كوب","3-4 أكواب مرق خضار في درجة حرارة الغرفة","خبز برجر نباتي","خس وطماطم ومخلل وبصل وأفوكادو","مايونيز حار نباتي"],
["سخّن الفرن مسبقًا على 350 درجة فهرنهايت (175 درجة مئوية).","ضع جميع مكونات برجر السيتان ما عدا غلوتين القمح الحيوي في محضّر الطعام واخلطها حتى تصبح ناعمة. بعد ذلك، أضف حوالي نصف غلوتين القمح الحيوي واخلط حتى يصبح ناعمًا في معظمه. ثم أضف النصف المتبقي واخلط حتى يمتزج في معظمه، دون إفراط في الخلط.","انقل الخليط إلى سطح نظيف، مثل لوح تقطيع أو سطح العمل، واعجن العجينة لمدة 30 ثانية تقريبًا، دون إفراط. وعندما ترى خيوط الغلوتين، تكون العجينة جاهزة. (انظر صور خطوات التحضير أعلاه للتوضيح.)","قسّمها إلى 8 قطع متساوية ليستوي الطهي بالتساوي. أستخدم ميزان المطبخ لجعلها متساوية تمامًا، لكن هذا ليس ضروريًا. يمكنك التقدير بالنظر.","شكّل كل قطعة على هيئة كرة ثم استخدم مدحاة العجين لتسطيح كل واحدة إلى قرص برجر. ستتمدد أثناء الطهي، لذا اجعلها أكثر تسطحًا قليلًا مما تريد أن تكون عليه النتيجة النهائية. وأثناء مد البرجر، يجب أن ترى أنه يرتد قليلًا.","استخدم وعاءً يصلح للفرن وله غطاء، مثل القدر الهولندي، وضع في قاعه طبقة رقيقة من مرق الخضار. ثم ضع أقراص السيتان فوقه على طبقات، مع إضافة مزيد من المرق بين طبقات الأقراص. أضف مرقًا كافيًا للتأكد من أن الأقراص مغطاة تمامًا.","ثم ضع الغطاء واخبزها في الفرن المسخن مسبقًا لمدة 80 دقيقة، مع قلبها بحذر عند الدقيقة 40. كن حذرًا جدًا عند القلب لمنع كسر الأقراص. وعند اكتمال الـ 80 دقيقة، أخرجها من الفرن.","إذا كنت تحضّرها مسبقًا، فانقل الأقراص إلى وعاء واحفظها في الثلاجة طوال الليل وأكمل الطهي في يوم التقديم. (احتفظ بالمرق لشربه، فهو لذيذ، فلا تسكبه! ;) )","تعامل معها كما تتعامل مع البرجر النيء. فهي ليست جاهزة للأكل مباشرة بعد خروجها من الفرن. أكمل برجر السيتان على الشواية، أو في مقلاة. ادهنه بقليل من الزيت لمنع الالتصاق ورشّ عليه الملح والفلفل إن رغبت. ثم اشوه أو اقلِه في المقلاة لبضع دقائق على كل جانب حتى يتحمّر ويسخن.","استمتع به مع خبز البرجر وجميع الإضافات المفضلة لديك."],
["إذا أمكن، حضّر البرجر قبل يوم واحد من الشواء. فطعمه أفضل عندما يُحفظ في الثلاجة طوال الليل ويُشوى في اليوم التالي. ومع ذلك، يبقى رائعًا إذا شويته مباشرة بعد تحضيره. زِن غلوتين القمح الحيوي للحصول على أدق النتائج. فالاعتماد على قياسات الأكواب قد يؤدي إلى برجر سيتان جاف وكثيف، إذ يميل القياس إلى كبس كمية أكبر من الدقيق في الأكواب مقارنة بالوزن. استخدم مرقًا مالحًا وغنيًا بالنكهة للحصول على أفضل النتائج لأنه لا يُضاف أي ملح آخر إلى هذه الوصفة. حاول تقسيم الخليط إلى 8 قطع متساوية الحجم ليستوي الطهي بالتساوي وتكون الأقراص متقاربة الحجم. وإذا أردتها مثالية، فاستخدم ميزان المطبخ لوزن القطع. افرد الأقراص مسطحة إلى حد كبير، لأنها ستكبر وسيتضاعف حجمها تقريبًا أثناء الطهي. أنت تريد أن تغلي الأقراص على نار هادئة في المرق وليس أن تفور بقوة، لتُطهى ببطء للحصول على أفضل قوام. لا ترفع درجة حرارة الفرن في محاولة لإنضاجها أسرع. تبقى أقراص برجر السيتان صالحة في الثلاجة لمدة 4-5 أيام أو تُجمَّد، موضوعة على طبقات يفصل بينها ورق الزبدة لمنع الالتصاق، لمدة تصل إلى 3 أشهر."],
{"For the seitan burgers":"لبرجر السيتان","For cooking":"للطهي","For serving":"للتقديم"})
R(9518240,"مسحوق مرق الخضار - خلطة الشوربة",
"مسحوق مرق الخضار هذا هو الحل لخلطة الشوربة لديك! إنه صحي وخالٍ من الدهون ويجهز في 5 دقائق. لن تشتري المرق الجاهز من المتجر مرة أخرى أبدًا!",
"10 حصص (1 ملعقة صغيرة لكل حصة)","حصة واحدة",
["2 ملعقة كبيرة خميرة غذائية","2 ملعقة كبيرة ملح البحر أو استخدم 1 ملعقة كبيرة لخيار قليل الصوديوم","1 ملعقة صغيرة بقدونس مجفف","1 ملعقة صغيرة مسحوق البصل","1 ملعقة صغيرة مسحوق الثوم","½ ملعقة صغيرة بذور الكرفس وليس ملح الكرفس","1 ورقة غار مجففة","¼ ملعقة صغيرة فلفل أسود، اختياري ولكنه موصى به"],
["ضع جميع المكونات في خلاط صغير أو محضّر طعام واخلطها حتى تصل إلى قوام المسحوق، أي حوالي 20 ثانية.","احفظه في برطمان نظيف أو وعاء محكم الإغلاق في الخزانة.","لتحضير المرق، اخلط 1 ملعقة صغيرة من خلطة الشوربة مع 1 كوب من الماء الساخن."],
["لمسحوق مرق خضار قليل الصوديوم، استخدم 1 ملعقة كبيرة من الملح لتقليل الصوديوم بنسبة 50% أو استخدم نصف ملعقة كبيرة من الملح لتقليل الصوديوم بنسبة 75%. ضاعف الوصفة مرتين أو ثلاثًا أو أربعًا كما تشاء. أحب تحضير دفعة كبيرة في كل مرة لتكون لديّ دائمًا كمية جاهزة للشوربات والأطباق المطبوخة بالفرن والخضار وغيرها. احفظ الخلطة في برطمان أو وعاء نظيف وجاف. احفظها في مكان بارد ومظلم، مثل الخزانة، أو إذا كنت تعيش في مناخ رطب، فيمكنك حفظها في الثلاجة للحفاظ على طزاجتها. استخدم مسحوق خلطة الشوربة بدلًا من مرق الخضار في أي وصفة. فقط اخلط 1 ملعقة صغيرة من خلطتك مع 1 كوب من الماء الساخن لكل كوب مطلوب. وإذا تخطيت الخلط إلى مسحوق وخلطت التوابل في وعاء، فستحتاج إلى حوالي ملعقة كبيرة من خلطة الشوربة لكل كوب من الماء الساخن. فعند الخلط، تصبح التوابل أكثر تركيزًا، و1 ملعقة صغيرة لكل كوب من الماء تعطي نتيجة جيدة. استخدم كمية أكثر أو أقل حسب ذوقك. واحرص أيضًا على حذف ورقة الغار إذا اخترت تخطي الخلط. لنسخة مرق \"الدجاج\"، أضف 1 ملعقة صغيرة من بهارات الدواجن. أو ½ ملعقة صغيرة من المريمية، و¼ ملعقة صغيرة من كل من الزعتر وإكليل الجبل."])
R(9518496,"هريس القرنبيط الصحي",
"هريس قرنبيط كريمي بنكهة الثوم وغني بالنكهة ومشبع بشكل لا يصدق!",
"4 حصص","حصة واحدة",
["6-8 أكواب زهيرات قرنبيط (حوالي رأس قرنبيط كبير واحد)","3-4 فصوص ثوم (مقشّرة)","ملح + فلفل (حسب الرغبة)"],
["ضع زهيرات القرنبيط وفصوص الثوم في قدر متوسط. غطِّها بالماء وأضف 1 ملعقة كبيرة من الملح. أوصلها إلى الغليان واطهِها لمدة 8-10 دقائق، أو حتى تلين الزهيرات عند غرزها بالشوكة.","استخدم ملعقة مثقبة لنقل القرنبيط والثوم المطبوخين إلى محضّر الطعام، واحتفظ بماء الطهي. ابدأ بخلط القرنبيط وأضف 2-4 ملاعق كبيرة من ماء الطهي، عند الحاجة، حتى يصبح الهريس ناعمًا وكريميًا.","وبعد أن يصبح ناعمًا بالقدر الذي تريده، يمكنك التخلص من ماء الطهي الزائد. تذوّق الهريس وأضف الملح والفلفل حسب ذوقك."],
[])
R(9523666,"زبدة الفول السوداني المنزلية - فيتامكس",
"لم يكن تحضير زبدة الفول السوداني المنزلية أسهل من ذلك مع فيتامكس، وتستخدم هذه الوصفة مكونًا واحدًا فقط، الفول السوداني!",
"2 كوب","1 ملعقة كبيرة",
["2-4 أكواب فول سوداني محمّص غير مملح","⅛-¼ ملعقة صغيرة ملح البحر، اختياري"],
["ضع الفول السوداني وملح البحر الاختياري إن استخدمته في فيتامكس. اخلط على سرعة عالية، مستخدمًا أداة الدفع (التامبر) لدفع الفول السوداني إلى الأسفل أثناء الخلط، حتى تصل إلى قوام ناعم. سيتحول الفول السوداني بسرعة من حبات كاملة إلى قطع مطحونة ثم إلى زبدة فول سوداني كريمية.","احفظه في برطمان أو وعاء نظيف محكم الإغلاق."],
["لتحضير زبدة الفول السوداني في فيتامكس، لا تستخدم أقل من 2 كوب من الفول السوداني. فستحتاج إلى حجم معين ليُخلط بشكل جيد. وإذا أردت تحضير أكثر من 4 أكواب في المرة الواحدة، فأقترح العمل على عدة دفعات. وإذا كنت تستخدم فولًا سودانيًا مملحًا، فاحذف ملح البحر الإضافي. احتفظت بزبدة الفول السوداني الخاصة بي في برطمان محكم الإغلاق في درجة حرارة الغرفة لمدة تصل إلى أسبوعين. يمكنك حفظها في الثلاجة لمدة أطول لكنها قد تتصلب قليلًا. ولن تتأثر النكهة."])
